// @vitest-environment jsdom
/* global describe, it, expect, beforeAll -- vitest globals (globals: true); declared for `eslint .` */
/**
 * publishingService characterization: the exported object keeps the same 89 methods in the same order,
 * and every method sends the same requests and returns / throws the same values under six scripted
 * responses (see serviceRecorder.ts). publishingService.golden.json was captured once from the
 * unmodified service (before it was split into domain modules) and is never regenerated by this test.
 */
import { fileURLToPath } from "node:url";
import { join, dirname } from "node:path";
import { readFileSync } from "node:fs";
import { publishingService } from "../../src/features/publishing/services/publishingService";
import { recordService, type MemberSpec } from "./serviceRecorder";

const here = dirname(fileURLToPath(import.meta.url));

const members: MemberSpec[] = JSON.parse(readFileSync(join(here, "publishingService.members.json"), "utf8"));
const golden: Record<string, unknown> = JSON.parse(readFileSync(join(here, "publishingService.golden.json"), "utf8"));

describe("publishingService", () => {
  let recorded: Record<string, unknown> = {};
  beforeAll(async () => {
    localStorage.setItem("token", "tok-1");
    recorded = await recordService(publishingService as unknown as Record<string, unknown>, members);
  }, 120_000);

  it("exposes the same methods in the same order", () => {
    expect(Object.keys(publishingService)).toEqual(members.map((m) => m.name));
    for (const m of members) expect(typeof (publishingService as any)[m.name]).toBe("function");
  });

  it("the golden covers every method", () => {
    expect(Object.keys(golden)).toEqual(members.map((m) => m.name));
  });

  it.each(members.map((m) => m.name))("%s: requests, results and side effects unchanged", (name) => {
    expect(recorded[name]).toEqual(golden[name]);
  });
});
